{"path":"assets/css/styles.css","content":"/* Lux gallery — clinical calm palette */
:root{
  --bg:#0f1722;
  --card:#0b1220;
  --muted:#9aa7b2;
  --accent1:#6b5bff;
  --accent2:#8bd3d6;
  --glass:rgba(255,255,255,0.04);
  --radius:12px;
  --max-width:1100px;
  font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:linear-gradient(180deg,var(--bg),#07101a 60%);color:#eaf4f7;line-height:1.45}
.container{max-width:var(--max-width);margin:0 auto;padding:36px}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:18px 36px;background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(6px)}
.brand{display:flex;flex-direction:column}
.brand .logo{height:28px}
.brand .tag{margin:2px 0 0;color:var(--muted);font-size:13px}
.nav{position:relative}
.nav-list{display:flex;gap:14px;list-style:none;padding:0;margin:0;align-items:center}
.nav-list a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:8px}
.nav-list a.cta{background:linear-gradient(90deg,var(--accent2),var(--accent1));color:#031018;font-weight:600}
.nav-toggle{display:none;background:none;border:1px solid rgba(255,255,255,0.03);padding:8px;border-radius:8px;color:var(--muted)}

.hero{padding:64px 0}
.hero-inner{max-width:980px;margin:0 auto;padding:48px;border-radius:16px;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));box-shadow:0 10px 30px rgba(11,15,20,0.6)}
.pattern-bg{background-image:url('../assets/img/pattern.svg');background-repeat:no-repeat;background-position:right top;background-size:40%;}
.hero-title{font-size:40px;margin:0 0 10px;color:#f6fcfd}
.hero-lead{color:var(--muted);margin:0 0 18px}
.hero-actions{display:flex;gap:12px;margin-bottom:8px}
.btn{display:inline-block;padding:12px 18px;border-radius:10px;text-decoration:none}
.btn-primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#021216;font-weight:700}
.btn-ghost{border:1px solid rgba(255,255,255,0.06);color:var(--muted);background:transparent}
.hero-meta{color:var(--muted);font-size:13px}

.myth-truth{padding:40px 0}
.myth-truth h2{margin:0 0 18px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}
.card{background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.02)}
.card h3{margin:0 0 8px;font-size:16px}
.card p{color:var(--muted);margin:0}

.pillars{padding:40px 0}
.pills{display:flex;gap:16px;flex-wrap:wrap}
.pills article{flex:1 1 260px;background:linear-gradient(180deg,rgba(11,13,18,0.6),rgba(255,255,255,0.02));padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.02)}
.pills h4{margin:0 0 8px}

.case-notes{padding:40px 0}
.case-notes ul{margin:0;padding-left:20px;color:var(--muted)}

.faq{padding:40px 0}
.faq-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.faq-grid h3{margin:0 0 6px}

.cta-band{padding:36px 0;background:linear-gradient(180deg,rgba(107,91,255,0.07),transparent)}
.cta-band .actions{display:flex;gap:12px;align-items:center}
.cta-band .link{color:var(--muted);text-decoration:underline}
.site-footer{padding:24px 36px;border-top:1px solid rgba(255,255,255,0.02);color:var(--muted)}

/* Responsive */
@media (max-width:880px){
  .nav-list{display:none;position:absolute;right:0;top:56px;background:var(--card);padding:12px;border-radius:12px;box-shadow:0 6px 20px rgba(2,6,10,0.6)}
  .nav-toggle{display:block}
  .hero-title{font-size:28px}
  .faq-grid{grid-template-columns:1fr}
}

/* Subtle decorative focus */
:focus{outline:2px dashed rgba(139,211,214,0.35);outline-offset:3px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav
  var toggle=document.querySelector('.nav-toggle');
  var list=document.querySelector('.nav-list');
  if(toggle && list){
    toggle.addEventListener('click',function(){
      var shown=list.style.display==='flex';
      list.style.display= shown ? 'none' : 'flex';
      list.style.flexDirection='column';
    });
  }

  // Populate year
  var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

  // Smooth scroll for anchors
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault();
      var id=this.getAttribute('href').slice(1);
      var el=document.getElementById(id);
      if(el) el.scrollIntoView({behavior:'smooth',block:'start'});
    });
  });

  // Simple FAQ accordion: click question toggles next paragraph
  document.querySelectorAll('.faq-grid > div').forEach(function(item){
    item.style.cursor='pointer';
    item.addEventListener('click',function(){
      var p=this.querySelector('p');
      if(!p) return;
      var open=p.style.display!=='none';
      p.style.display=open ? 'none' : 'block';
    });
    // initialize collapsed on small screens
    var p=item.querySelector('p'); if(p && window.innerWidth<880) p.style.display='none';
  });
})();"} 
